const lv_image_dsc_t* oyc_face_get(const char* emotion, bool blink, bool big) {
    const char* name = emotion ? emotion : "neutral";
    for (size_t i = 0; i < sizeof(s_aliases)/sizeof(s_aliases[0]); i++)
        if (strcmp(name, s_aliases[i].alias) == 0) { name = s_aliases[i].name; break; }
    const oyc_face_entry_t* t = big ? s_faces64 : s_faces48;
    size_t n = big ? sizeof(s_faces64)/sizeof(s_faces64[0]) : sizeof(s_faces48)/sizeof(s_faces48[0]);
    for (size_t i = 0; i < n; i++)
        if (strcmp(name, t[i].name) == 0) return blink ? t[i].blink : t[i].open;
    return blink ? t[0].blink : t[0].open;
}
